import{z as o,x as d,o as r,c as D,q as l,j as s,D as e,d as t,s as i,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"ECDH 与 X25519","description":"","frontmatter":{"title":"ECDH 与 X25519","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ecdh-x25519.md","filePath":"cs/ecdh-x25519.md","lastUpdated":1791063341000}'),B={name:"cs/ecdh-x25519.md"};function p(C,a,F,h,c,u){const A=d("Mermaid");return r(),D("div",null,[a[2]||(a[2]=l('<h1 id="ecdh-与-x25519" tabindex="-1">ECDH 与 X25519 <a class="header-anchor" href="#ecdh-与-x25519" aria-label="Permalink to &quot;ECDH 与 X25519&quot;">​</a></h1><div class="epigraph"><p>椭圆曲线 DH 用短得多的密钥达到与有限域 DH 同类的协商目标。X25519 把曲线、编码与钳位私钥收成一套难误用的合同，而不是「任意一条曲线都行」。</p><footer>—— Koblitz / Miller 椭圆曲线公钥；Bernstein, Curve25519；RFC 7748</footer></div><p>上一课<a href="/cs/rsa-attacks">RSA 攻击面</a>劝许多协议离开 RSA 封装。主干<a href="/cs/elliptic-curve-group">椭圆曲线</a>已有群直觉。缺口是<strong>ECDH 作为密钥协商</strong>：共享秘密是点的坐标派生，不是加密消息。X25519 是工程默认之一。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>有限域 DH 公钥大；ECDH 在合适曲线上密钥约 256 比特。小群、错误曲线、点不在曲线上，会把协商拉到弱群——本课只陈述必须校验或用蒙哥马利曲线避开一类检查。X25519：Curve25519、固定基、钳位。缺口是协商合同，不重推曲线方程。</p><p><span class="marginnote">数字实例：256 比特的椭圆曲线密钥，安全强度大致相当于 3072 比特的有限域 DH 或 RSA。而 RSA 3072 公钥要 384 字节，X25519 公钥只要 32 字节——握手包更小、计算更快，这正是 TLS 1.3 等协议全面转向 ECDH 的直接原因。</span></p><h3 id="共享秘密还要-kdf" tabindex="-1">共享秘密还要 KDF <a class="header-anchor" href="#共享秘密还要-kdf" aria-label="Permalink to &quot;共享秘密还要 KDF&quot;">​</a></h3><p>ECDH 输出不是 AEAD 键。HKDF 更后；本课只要求「再派生」。</p><p><span class="marginnote">RFC 7748。TLS 1.3 的 x25519 是命名群。不要把任意自选曲线当同等安全。本课不给弱曲线参数的利用步骤。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照 DH：\\(g^a,g^b\\mapsto g^{ab}\\) 变成标量乘。陈述 X25519 的 32 字节编码。认证仍缺：无签名或预共享时，ECDH 对中间人成功。证书课已在主干；本进阶课后面信道单元再钉链验证细节。</p><p><span class="marginnote">常见误区：以为协商算出来的数能直接当 AES 密钥用。实际上共享秘密是曲线点的坐标派生值，不是均匀随机的比特串，也不区分「加密用」「认证用」；必须再过一遍 KDF（如 HKDF）派生出规整的密钥材料，跳过这一步会留下很难察觉的弱点。</span></p>',13)),(r(),s(n,null,{default:e(()=>[i(A,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%A0%87%E9%87%8F%20a%22%5D%20--%3E%20P%5B%22X25519%20%E5%85%AC%E9%92%A5%22%5D%0A%20%20B%5B%22%E5%AF%B9%E7%AB%AF%E5%85%AC%E9%92%A5%22%5D%20--%3E%20SS%5B%22%E5%85%B1%E4%BA%AB%E7%A7%98%E5%AF%86%22%5D%0A%20%20A%20--%3E%20SS%0A%20%20SS%20--%3E%20KDF%5B%22%E5%90%8E%E8%AF%BE%E6%B4%BE%E7%94%9F%20AEAD%20%E9%94%AE%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"前向保密来自临时标量。长期静态 ECDH 没有同样的遗忘性。实现必须用恒定时间标量乘；曲线选择把一类无效点问题收进规格。身份绑定仍是 PKI 或预共享。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"前向保密（forward secrecy）说的是：长期身份密钥将来丢了，过去的通信记录也解不开。直觉类比：每次见面用一次性保险箱当场装秘密、用完砸掉钥匙——小偷日后偷到万能钥匙（长期私钥），也只能开未来的箱子，翻不动已经砸掉钥匙的旧箱子。")],-1)),a[6]||(a[6]=E("p",null,"临时标量和长期静态密钥，泄露时的损失范围差在哪？",-1)),(r(),s(n,null,{default:e(()=>[i(A,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20EPH%5B%22%E4%B8%B4%E6%97%B6%E6%A0%87%E9%87%8F%EF%BC%9A%E6%AF%8F%E4%BC%9A%E8%AF%9D%E4%B8%80%E6%8D%A2%22%5D%0A%20%20%20%20E1%5B%22%E6%9C%AC%E4%BC%9A%E8%AF%9D%E6%A0%87%E9%87%8F%E8%A2%AB%E6%B3%84%E9%9C%B2%22%5D%20--%3E%20E2%5B%22%E5%8F%AA%E6%9A%B4%E9%9C%B2%E6%9C%AC%E4%BC%9A%E8%AF%9D%E7%9A%84%E5%AF%86%E9%92%A5%22%5D%0A%20%20%20%20E2%20--%3E%20E3%5B%22%E5%8E%86%E5%8F%B2%E4%BC%9A%E8%AF%9D%E4%B8%8D%E5%8F%97%E5%BD%B1%E5%93%8D%EF%BC%9A%E5%89%8D%E5%90%91%E4%BF%9D%E5%AF%86%22%5D%0A%20%20end%0A%20%20subgraph%20ST%5B%22%E9%95%BF%E6%9C%9F%E9%9D%99%E6%80%81%20ECDH%22%5D%0A%20%20%20%20S1%5B%22%E9%95%BF%E6%9C%9F%E7%A7%81%E9%92%A5%E8%A2%AB%E6%B3%84%E9%9C%B2%22%5D%20--%3E%20S2%5B%22%E6%89%80%E6%9C%89%E6%9B%BE%E7%94%A8%E5%AE%83%E5%8D%8F%E5%95%86%E7%9A%84%E4%BC%9A%E8%AF%9D%E9%83%BD%E5%8F%AF%E8%A7%A3%E5%BC%80%22%5D%0A%20%20end%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写全部 NIST 曲线清单。下一课 ECDSA/EdDSA：同一类群上的签名，与 DH 分工，密钥不要混用语义。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RSA 封装之外，ECDH 做临时协商。</li><li>X25519 是难误用的 Curve25519 合同。</li><li>输出必须再 KDF；无认证则中间人成功。</li><li>下一课：同群上的签名 EdDSA/ECDSA。</li><li>出处：RFC 7748；Bernstein, Curve25519；对照 Diffie and Hellman, 1976。</li></ul>',4))])}const f=o(B,[["render",p]]);export{S as __pageData,f as default};
